from collections import deque
def rule(I, colors):
    H,W=len(I),len(I[0])
    bg={5,9}
    start=[(r,c) for r in range(H) for c in range(W) if I[r][c] not in bg]
    d=[[None]*W for _ in range(H)]
    dq=deque(start)
    for s in start: d[s[0]][s[1]]=0
    while dq:
        r,c=dq.popleft()
        dd=d[r][c]
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and I[nr][nc] not in bg and d[nr][nc] is None:
                d[nr][nc]=dd+1; dq.append((nr,nc))
    O=[row[:] for row in I]
    for r in range(H):
        for c in range(W):
            if I[r][c] not in bg and d[r][c] is not None:
                O[r][c]=colors[d[r][c]%2]
    return O
